from collections import defaultdict

def generateSentences(synonyms, text):
    parent = dict()
    def find(x):
        parent.setdefault(x, x)
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        parent[find(x)] = find(y)
    for a, b in synonyms:
        union(a, b)
    groups = defaultdict(set)
    for a, b in synonyms:
        groups[find(a)].add(a)
        groups[find(b)].add(b)
    for group in groups.values():
        for w in group:
            groups[w] = group
    words = text.split()
    res = []
    def dfs(i, path):
        if i == len(words):
            res.append(' '.join(path))
            return
        w = words[i]
        candidates = sorted(groups[w]) if w in groups else [w]
        for cand in candidates:
            dfs(i+1, path + [cand])
    dfs(0, [])
    return sorted(res)
